  "implementation": "def solve(case):
    import json

    nodes = case.get('nodes')
    core_distance = case.get('core_distance')
    distances = case.get('distances')

    if not isinstance(nodes, list) or not isinstance(core_distance, dict) or not isinstance(distances, list):
        raise ValueError('Missing or invalid fields in case')

    n = len(nodes)
    # Validate core_distance covers all nodes
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f'Node {node} missing from core_distance')
    # Validate distances cover all unordered pairs (N*(N-1)/2)
    expected_pair_count = n * (n - 1) // 2
    if len(distances) != expected_pair_count:
        raise ValueError(f'Expected {expected_pair_count} distances, got {len(distances)}')
    # Validate distances format and completeness
    seen_pairs = set()
    for entry in distances:
        if not isinstance(entry, list) or len(entry) != 3:
            raise ValueError('Invalid distance entry')
        u, v, d = entry
        if not (isinstance(u, str) and isinstance(v, str) and isinstance(d, (int, float))):
            raise ValueError('Distance entry must have two strings and a number')
        if u == v:
            raise ValueError('Self-distance not allowed')
        key = (min(u, v), max(u, v))
        if key in seen_pairs:
            raise ValueError('Duplicate distance entry')
        seen_pairs.add(key)
        if u not in core_distance or v not in core_distance:
            raise ValueError('Distance references unknown node')
    # Build all edges with mutual reachability
    edges = []
    for (u, v, d) in distances:
        mr = max(core_distance[u], core_distance[v], d)
        if u > v:
            u, v = v, u  # canonical order
        edges.append((mr, u, v))
    # Sort by mutual_reachability, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find structure
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError('Graph is disconnected')
    # Sort output for determinism
    mst_edges.sort(key=lambda x: (x[2], x[0], x[1]))
    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
